import Foundation
import XCTest
@testable import FrankenTermKit

/// All positive encrypted containers and PBKDF2 vectors were generated by
/// OpenSSL, without using a production encoder. TestCryptography supplies the
/// existing independent AES/identity oracle on Linux; the wrapper deliberately
/// executes the production CryptoExtras PBKDF2 on every successful unlock.
@MainActor
final class EncryptedPKCS8SourceKeyTests: XCTestCase {
    private let crypto = PKCS8TestCryptography()

    func testOpenSSLMatrixPreservesEveryPrivateComponentThroughThePublicUnlocker() async throws {
        let fixtures = try PKCS8Fixtures.load()
        XCTAssertEqual(fixtures.keys.count, 16)
        XCTAssertEqual(Set(fixtures.keys.map(\.prf)), Set(PKCS8PBKDF2PRF.allCases.map(\.rawValue)))
        XCTAssertEqual(Set(fixtures.keys.map(\.aesKeyBits)), Set([128, 192, 256]))
        XCTAssertEqual(Set(fixtures.keys.map(\.algorithm)), Set(["ssh-rsa"] + SSHECDSACurve.allCases.map(\.algorithm)))
        XCTAssertTrue(fixtures.keys.contains { $0.iterations == EncryptedPKCS8SourceKey.maximumIterations })
        for fixture in fixtures.keys {
            let reference = try workspace(fixture).credentials[0]
            var picker = OpenSSHSourceKeyUnlocker(using: crypto)
            let selected = try request(picker.select(pem: Data(fixture.encryptedPEM.utf8), reference: reference))
            XCTAssertEqual(selected.credentialID, reference.id)
            XCTAssertEqual(selected.algorithm, fixture.algorithm)
            XCTAssertEqual(selected.fingerprint, fixture.fingerprint)
            XCTAssertEqual(selected.protection, .encryptedPKCS8(prf: fixture.function,
                iterations: fixture.iterations, aesKeyBits: fixture.aesKeyBits))
            XCTAssertNil(selected.bcryptRounds)
            let record = try picker.unlock(requestID: selected.id, passphrase: Data(fixtures.passphrase.utf8))
            XCTAssertNil(picker.request)
            XCTAssertEqual(record.publicBlob, fixture.publicBlob, fixture.id)
            XCTAssertEqual(try PrivateKeyRecord.validateContainer(record.container, using: crypto), fixture.publicBlob, fixture.id)
            let clear = try PrivateKeyRecord.fromPEM(fixture.clearPEM(), credentialID: reference.id, using: crypto)
            XCTAssertEqual(try privateIdentityDigest(record), try privateIdentityDigest(clear), fixture.id)
            XCTAssertThrowsError(try picker.unlock(requestID: selected.id, passphrase: Data(fixtures.passphrase.utf8))) {
                XCTAssertEqual($0 as? FTError, .stale)
            }
        }
    }

    func testUnlockedRSAAndECDSARecordsSurviveAuthenticatedAirGapTransfer() async throws {
        let fixtures = try PKCS8Fixtures.load()
        for identifier in ["openssl-default-rsa2048", "hmacSHA256-aes192"] {
            let fixture = try XCTUnwrap(fixtures.keys.first { $0.id == identifier })
            let document = try workspace(fixture)
            var picker = OpenSSHSourceKeyUnlocker(using: crypto)
            let selected = try request(picker.select(pem: Data(fixture.encryptedPEM.utf8), reference: document.credentials[0]))
            let record = try picker.unlock(requestID: selected.id, passphrase: Data(fixtures.passphrase.utf8))
            let archive = try AirGapArchive(workspace: document, keys: [record], using: crypto)
            let sealed = try FTAG.seal(archive, using: crypto)
            let restored = try FTAG.open(sealed.envelope, code: sealed.code, using: crypto)
            XCTAssertEqual(restored.workspace.raw, document.raw)
            XCTAssertEqual(restored.keys.count, 1)
            XCTAssertEqual(restored.keys[0].publicBlob, fixture.publicBlob)
            XCTAssertEqual(try privateIdentityDigest(restored.keys[0]), try privateIdentityDigest(record))
            XCTAssertEqual(try SSHUserAuthenticationSigner.publicIdentity(privateContainer: restored.keys[0].container).fingerprint,
                           fixture.fingerprint)
        }
    }

    func testHiddenIdentityIsCheckedAfterDecryptionAgainstTheApprovedReference() async throws {
        let fixtures = try PKCS8Fixtures.load()
        let encrypted = try XCTUnwrap(fixtures.keys.first { $0.id == "hmacSHA256-aes128" })
        let other = try XCTUnwrap(fixtures.keys.first { $0.id == "hmacSHA256-aes192" })
        for document in [try workspace(other), try workspace(encrypted, fingerprint: other.fingerprint)] {
            var picker = OpenSSHSourceKeyUnlocker(using: crypto)
            let reference = document.credentials[0]
            let selected = try request(picker.select(pem: Data(encrypted.encryptedPEM.utf8), reference: reference))
            // The encrypted file provides no clear public identity. The prompt
            // names the approved reference until actual decryption proves it.
            XCTAssertEqual(selected.algorithm, reference.algorithm)
            XCTAssertEqual(selected.fingerprint, reference.fingerprint)
            XCTAssertThrowsError(try picker.unlock(requestID: selected.id, passphrase: Data(fixtures.passphrase.utf8))) {
                XCTAssertEqual($0 as? OpenSSHSourceKeyError, .identityMismatch)
            }
        }
    }

    func testWrongPassphraseAndCiphertextDamageHaveContentFreeFailures() async throws {
        let fixtures = try PKCS8Fixtures.load(), fixture = fixtures.keys[3]
        let reference = try workspace(fixture).credentials[0]
        var picker = OpenSSHSourceKeyUnlocker(using: crypto)
        let selected = try request(picker.select(pem: Data(fixture.encryptedPEM.utf8), reference: reference))
        XCTAssertThrowsError(try picker.unlock(requestID: selected.id, passphrase: Data("wrong public test password".utf8))) {
            XCTAssertEqual($0 as? OpenSSHSourceKeyError, .incorrectPassphraseOrDamagedKey)
            XCTAssertFalse($0.localizedDescription.contains(fixtures.passphrase))
        }
        XCTAssertEqual(picker.request?.attemptsRemaining, 4)
        let original = try PKCS8TestDER.parse(pem: fixture.encryptedPEM)
        for index in [0, original.node([1]).bytes.count - 1] {
            var changed = original, payload = original.node([1])
            payload.bytes[index] ^= 0x80
            changed.replace([1], with: payload)
            let request = try self.request(picker.select(pem: changed.pem(), reference: reference))
            XCTAssertThrowsError(try picker.unlock(requestID: request.id, passphrase: Data(fixtures.passphrase.utf8))) {
                XCTAssertEqual($0 as? OpenSSHSourceKeyError, .incorrectPassphraseOrDamagedKey)
            }
        }
        let source = try EncryptedPKCS8SourceKey(pem: Data(fixture.encryptedPEM.utf8))
        XCTAssertEqual(String(describing: source), "EncryptedPKCS8SourceKey([redacted])")
        XCTAssertEqual(String(reflecting: source), "EncryptedPKCS8SourceKey([redacted])")
    }

    func testUnlockerRetiresReplacedAndCancelledRequestsAndBoundsPasswordAttempts() async throws {
        let fixtures = try PKCS8Fixtures.load(), fixture = fixtures.keys[3]
        let audit = PKCS8TestCryptography(), reference = try workspace(fixture).credentials[0]
        var picker = OpenSSHSourceKeyUnlocker(using: audit)
        let old = try request(picker.select(pem: Data(fixture.encryptedPEM.utf8), reference: reference))
        let latest = try request(picker.select(pem: Data(fixture.encryptedPEM.utf8), reference: reference))
        XCTAssertNotEqual(old.id, latest.id)
        XCTAssertThrowsError(try picker.cancel(requestID: old.id)) { XCTAssertEqual($0 as? FTError, .stale) }
        XCTAssertThrowsError(try picker.unlock(requestID: old.id, passphrase: Data([1]))) { XCTAssertEqual($0 as? FTError, .stale) }
        for password in [Data(), Data(repeating: 1, count: 1025)] {
            XCTAssertThrowsError(try picker.unlock(requestID: latest.id, passphrase: password)) {
                XCTAssertEqual($0 as? FTError, .limit("source_key.passphrase"))
            }
        }
        XCTAssertEqual(audit.calls.snapshot.kdf, 0)
        XCTAssertEqual(picker.request?.attemptsRemaining, 5)
        for attempt in 1...5 {
            XCTAssertThrowsError(try picker.unlock(requestID: latest.id, passphrase: Data("wrong".utf8))) {
                XCTAssertEqual($0 as? OpenSSHSourceKeyError,
                               attempt == 5 ? .attemptsExhausted : .incorrectPassphraseOrDamagedKey)
            }
        }
        XCTAssertEqual(audit.calls.snapshot.kdf, 5)
        XCTAssertNil(picker.request)
        XCTAssertThrowsError(try picker.unlock(requestID: latest.id, passphrase: Data(fixtures.passphrase.utf8))) {
            XCTAssertEqual($0 as? FTError, .stale)
        }
        let cancelled = try request(picker.select(pem: Data(fixture.encryptedPEM.utf8), reference: reference))
        try picker.cancel(requestID: cancelled.id)
        XCTAssertNil(picker.request)
        XCTAssertThrowsError(try picker.unlock(requestID: cancelled.id, passphrase: Data(fixtures.passphrase.utf8))) {
            XCTAssertEqual($0 as? FTError, .stale)
        }
    }

    func testCancellationBeforeKDFAndAfterNativeWorkRetiresTheExactRequest() async throws {
        let fixtures = try PKCS8Fixtures.load(), fixture = fixtures.keys[3]
        let reference = try workspace(fixture).credentials[0]
        for behavior in [PKCS8TestCryptography.Behavior.denied, .cancelAfterKDF, .cancelAfterAES] {
            let audit = PKCS8TestCryptography(behavior: behavior)
            let operation = Task { () throws -> Bool in
                var picker = OpenSSHSourceKeyUnlocker(using: audit)
                let selected = try self.request(picker.select(pem: Data(fixture.encryptedPEM.utf8), reference: reference))
                if behavior == .denied { withUnsafeCurrentTask { $0?.cancel() } }
                do {
                    _ = try picker.unlock(requestID: selected.id, passphrase: Data(fixtures.passphrase.utf8))
                    return false
                } catch is CancellationError { return picker.request == nil }
            }
            let retired = try await operation.value
            XCTAssertTrue(retired)
            XCTAssertEqual(audit.calls.snapshot.kdf, behavior == .denied ? 0 : 1)
            XCTAssertEqual(audit.calls.snapshot.aes, behavior == .cancelAfterAES ? 1 : 0)
        }
    }

    func testPBKDF2ProductionMatchesIndependentOpenSSLBinaryPasswordVectors() async throws {
        let fixtures = try PKCS8Fixtures.load()
        XCTAssertEqual(fixtures.vectors.count, 12)
        for vector in fixtures.vectors {
            let password = try Data(ftHex: vector.passphraseHex), salt = try Data(ftHex: vector.saltHex)
            let expected = try Data(ftHex: vector.expectedHex)
            XCTAssertEqual(try PKCS8SourcePrimitives.pbkdf2(passphrase: password, salt: salt,
                iterations: vector.iterations, prf: vector.function, outputByteCount: vector.outputByteCount), expected)
            #if canImport(CTestOpenSSL)
            XCTAssertEqual(try TestCryptography().pbkdf2(passphrase: password, salt: salt,
                iterations: vector.iterations, prf: vector.function, outputByteCount: vector.outputByteCount), expected)
            #endif
        }
    }

    func testPBKDF2PrimitiveRejectsUnboundedInputsBeforeNativeWork() async throws {
        let password = Data([1]), salt = Data(repeating: 1, count: 8)
        for iterations in [UInt32(0), 1_000_001, UInt32.max] {
            XCTAssertThrowsError(try PKCS8SourcePrimitives.pbkdf2(passphrase: password, salt: salt,
                iterations: iterations, prf: .hmacSHA256, outputByteCount: 32))
        }
        for count in [0, 7, 65] {
            XCTAssertThrowsError(try PKCS8SourcePrimitives.pbkdf2(passphrase: password, salt: Data(repeating: 1, count: count),
                iterations: 1, prf: .hmacSHA256, outputByteCount: 32))
        }
        for password in [Data(), Data(repeating: 1, count: 1025)] {
            XCTAssertThrowsError(try PKCS8SourcePrimitives.pbkdf2(passphrase: password, salt: salt,
                iterations: 1, prf: .hmacSHA256, outputByteCount: 32))
        }
        for count in [-1, 0, 15, 17, 23, 25, 31, 33, Int.max] {
            XCTAssertThrowsError(try PKCS8SourcePrimitives.pbkdf2(passphrase: password, salt: salt,
                iterations: 1, prf: .hmacSHA256, outputByteCount: count))
        }
    }

    func testExplicitMatchingKeyLengthAndOmittedSHA1DefaultInteroperate() async throws {
        let fixtures = try PKCS8Fixtures.load()
        for fixture in fixtures.keys.prefix(3) {
            var changed = try PKCS8TestDER.parse(pem: fixture.encryptedPEM)
            let path = [0, 1, 0, 1]
            var derivation = changed.node(path)
            XCTAssertEqual(derivation.children.count, 2, "OpenSSL omits the ASN.1 default SHA1 PRF")
            derivation.children.append(.integer(UInt64(fixture.aesKeyBits / 8)))
            changed.replace(path, with: derivation)
            var picker = OpenSSHSourceKeyUnlocker(using: crypto)
            let selected = try request(picker.select(pem: changed.pem(), reference: workspace(fixture).credentials[0]))
            XCTAssertEqual(selected.protection, .encryptedPKCS8(prf: .hmacSHA1,
                iterations: fixture.iterations, aesKeyBits: fixture.aesKeyBits))
            XCTAssertEqual(try picker.unlock(requestID: selected.id, passphrase: Data(fixtures.passphrase.utf8)).publicBlob,
                           fixture.publicBlob)
        }
    }

    func testMalformedAndExpensiveEnvelopesAreRefusedBeforeAnyPromptOrKDF() async throws {
        let fixtures = try PKCS8Fixtures.load(), fixture = fixtures.keys[3]
        let original = try PKCS8TestDER.parse(pem: fixture.encryptedPEM)
        let derivationPath = [0, 1, 0, 1], iterationPath = derivationPath + [1]
        var invalid: [(String, Data)] = []
        func replacing(_ name: String, _ path: [Int], _ value: PKCS8TestDER) {
            var changed = original; changed.replace(path, with: value)
            invalid.append((name, changed.pem()))
        }
        for (name, path) in [("encryption", [0, 0]), ("KDF", [0, 1, 0, 0]),
                             ("PRF", derivationPath + [2, 0]), ("cipher", [0, 1, 1, 0])] {
            replacing(name, path, .init(tag: 6, bytes: Data([0x2a, 3, 4])))
        }
        for count in [0, 7, 65] { replacing("salt \(count)", derivationPath + [0], .init(tag: 4, bytes: Data(repeating: 1, count: count))) }
        replacing("salt source", derivationPath + [0], .sequence([]))
        for value in [Data(), Data([0]), Data([0xff]), Data([0, 1]), Data([0x0f, 0x42, 0x41]),
                      Data([0, 0xff, 0xff, 0xff, 0xff]), Data(repeating: 1, count: 6)] {
            replacing("iteration integer", iterationPath, .init(tag: 2, bytes: value))
        }
        for count in [0, 15, 17] { replacing("IV \(count)", [0, 1, 1, 1], .init(tag: 4, bytes: Data(repeating: 1, count: count))) }
        for count in [0, 15, 17, 16 * 1024] { replacing("ciphertext \(count)", [1], .init(tag: 4, bytes: Data(repeating: 1, count: count))) }
        var derivation = original.node(derivationPath)
        derivation.children.insert(.integer(32), at: 2) // fixture uses AES-128
        replacing("mismatched key length", derivationPath, derivation)
        var prf = original.node(derivationPath + [2])
        prf.children.removeLast()
        replacing("missing PRF NULL", derivationPath + [2], prf)
        replacing("nonempty PRF NULL", derivationPath + [2, 1], .init(tag: 5, bytes: Data([0])))
        replacing("explicit ASN.1 default", derivationPath + [2, 0],
                  .init(tag: 6, bytes: Data([0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 2, 7])))
        for path in [[], [0], [0, 1], [0, 1, 0], derivationPath, derivationPath + [2], [0, 1, 1]] {
            var sequence = original.node(path); sequence.children.append(.init(tag: 5, bytes: Data()))
            replacing("trailing sequence field", path, sequence)
        }
        let wire = original.encoded()
        invalid.append(("truncated DER", PKCS8TestDER.pem(Data(wire.dropLast()))))
        invalid.append(("trailing DER", PKCS8TestDER.pem(wire + Data([0]))))
        invalid.append(("indefinite DER", PKCS8TestDER.pem(Data([0x30, 0x80]) + original.payload + Data([0, 0]))))
        invalid.append(("nonminimal DER", PKCS8TestDER.pem(Data([0x30, 0x82, 0, UInt8(original.payload.count)]) + original.payload)))
        invalid.append(("overflow DER", PKCS8TestDER.pem(Data([0x30, 0x84, 0xff, 0xff, 0xff, 0xff]))))
        invalid.append(("PEM trailer", Data((fixture.encryptedPEM + "extra").utf8)))
        invalid.append(("multiple PEMs", Data((fixture.encryptedPEM + fixture.encryptedPEM).utf8)))
        invalid.append(("PEM limit", Data(repeating: 65, count: FTLimit.key + 1)))
        let denied = PKCS8TestCryptography(behavior: .denied)
        var picker = OpenSSHSourceKeyUnlocker(using: denied)
        let reference = try workspace(fixture).credentials[0]
        for (name, pem) in invalid {
            XCTAssertThrowsError(try picker.select(pem: pem, reference: reference), name) { XCTAssertNotNil($0 as? FTError, name) }
            XCTAssertNil(picker.request, name)
        }
        XCTAssertEqual(denied.calls.snapshot.kdf, 0)
        XCTAssertEqual(denied.calls.snapshot.aes, 0)
    }

    func testShortKDFOutputCannotReachAESAndPassiveArchiveImportStillRefusesEncryption() async throws {
        let fixture = try PKCS8Fixtures.load().keys[3]
        let audit = PKCS8TestCryptography(behavior: .shortKDF)
        var picker = OpenSSHSourceKeyUnlocker(using: audit)
        let selected = try request(picker.select(pem: Data(fixture.encryptedPEM.utf8), reference: workspace(fixture).credentials[0]))
        XCTAssertThrowsError(try picker.unlock(requestID: selected.id, passphrase: Data([1]))) {
            XCTAssertEqual($0 as? FTError, .malformed("source_key.kdf_output"))
        }
        XCTAssertEqual(audit.calls.snapshot.kdf, 1)
        XCTAssertEqual(audit.calls.snapshot.aes, 0)
        XCTAssertThrowsError(try PrivateKeyRecord.fromPEM(Data(fixture.encryptedPEM.utf8), credentialID: "key", using: crypto))
    }

    private func request<C: AirGapCryptography>(_ selection: OpenSSHSourceKeyUnlocker<C>.Selection) throws -> OpenSSHSourceKeyUnlocker<C>.Request {
        guard case .passphraseRequired(let value) = selection else { throw FTError.malformed("test.expected_prompt") }
        return value
    }
    private func workspace(_ fixture: PKCS8Fixtures.Key, fingerprint: String? = nil) throws -> WorkspaceDocument {
        var root = try XCTUnwrap(JSONSerialization.jsonObject(with: sampleManifest(fingerprint: fingerprint ?? fixture.fingerprint)) as? [String: Any])
        var value = try XCTUnwrap(root["workspace"] as? [String: Any])
        var credentials = try XCTUnwrap(value["credentials"] as? [[String: Any]])
        credentials[0]["algorithm"] = fixture.algorithm; value["credentials"] = credentials; root["workspace"] = value
        return try WorkspaceDocument(data: JSONSerialization.data(withJSONObject: root))
    }
    private func privateIdentityDigest(_ record: PrivateKeyRecord) throws -> Data {
        var outer = ByteCursor(record.container)
        _ = try outer.take(15)
        for _ in 0..<3 { _ = try outer.sshString() }
        _ = try outer.uint(4); _ = try outer.sshString()
        var inner = ByteCursor(try outer.sshString())
        _ = try inner.take(8)
        let algorithm = try inner.sshString()
        for _ in 0..<(algorithm == Data("ssh-rsa".utf8) ? 7 : 4) { _ = try inner.sshString() }
        return crypto.sha256(inner.data.subdata(in: 8..<inner.offset))
    }
}

private struct PKCS8Fixtures: Decodable, Sendable {
    struct Key: Decodable, Sendable {
        let id, sourceFile, sourceID, algorithm, fingerprint, publicKey, prf, encryptedPEM: String
        let iterations: UInt32, aesKeyBits: Int
        var function: PKCS8PBKDF2PRF { PKCS8PBKDF2PRF(rawValue: prf)! }
        var publicBlob: Data { Data(base64Encoded: publicKey.split(separator: " ")[1].description)! }
        func clearPEM() throws -> Data {
            struct Source: Decodable { struct Key: Decodable { let id, pkcs8PEM: String }; let keys: [Key] }
            guard ["rsa-source-keys.json", "legacy-ecdsa-source-keys.json"].contains(sourceFile) else { throw FTError.malformed("test.fixture") }
            let source = try JSONDecoder().decode(Source.self, from: Data(contentsOf: PKCS8Fixtures.directory.appendingPathComponent(sourceFile)))
            guard let key = source.keys.first(where: { $0.id == sourceID }) else { throw FTError.malformed("test.fixture") }
            return Data(key.pkcs8PEM.utf8)
        }
    }
    struct Vector: Decodable, Sendable {
        let prf, passphraseHex, saltHex, expectedHex: String
        let iterations: UInt32, outputByteCount: Int
        var function: PKCS8PBKDF2PRF { PKCS8PBKDF2PRF(rawValue: prf)! }
    }
    let passphrase: String, keys: [Key], vectors: [Vector]
    static var directory: URL {
        (0..<6).reduce(URL(fileURLWithPath: #filePath)) { value, _ in value.deletingLastPathComponent() }
            .appendingPathComponent("fixtures/ios-airgap")
    }
    static func load() throws -> Self {
        try JSONDecoder().decode(Self.self, from: Data(contentsOf: directory.appendingPathComponent("encrypted-pkcs8-source-keys.json")))
    }
}

private final class PKCS8Calls: @unchecked Sendable {
    private let lock = NSLock()
    private var kdf = 0, aes = 0
    var snapshot: (kdf: Int, aes: Int) { lock.withLock { (kdf, aes) } }
    func derived() { lock.withLock { kdf += 1 } }
    func decrypted() { lock.withLock { aes += 1 } }
}

private struct PKCS8TestCryptography: AirGapCryptography {
    enum Behavior: Equatable, Sendable { case normal, denied, shortKDF, cancelAfterKDF, cancelAfterAES }
    let base = TestCryptography(), calls = PKCS8Calls()
    let behavior: Behavior
    init(behavior: Behavior = .normal) { self.behavior = behavior }
    func sha256(_ bytes: Data) -> Data { base.sha256(bytes) }
    func hmacSHA1(key: Data, message: Data) throws -> Data { try base.hmacSHA1(key: key, message: message) }
    func randomBytes(count: Int) throws -> Data { try base.randomBytes(count: count) }
    func seal(_ plaintext: Data, secret: Data, salt: Data, nonce: Data, aad: Data) throws -> Data { try base.seal(plaintext, secret: secret, salt: salt, nonce: nonce, aad: aad) }
    func open(_ ciphertextAndTag: Data, secret: Data, salt: Data, nonce: Data, aad: Data) throws -> Data { try base.open(ciphertextAndTag, secret: secret, salt: salt, nonce: nonce, aad: aad) }
    func ed25519PublicKey(seed: Data) throws -> Data { try base.ed25519PublicKey(seed: seed) }
    func ecdsaPublicKey(scalar: Data, curve: SSHECDSACurve) throws -> Data { try base.ecdsaPublicKey(scalar: scalar, curve: curve) }
    func importECDSAPrivateScalar(_ der: Data, curve: SSHECDSACurve) throws -> Data { try base.importECDSAPrivateScalar(der, curve: curve) }
    func bcryptPBKDF(passphrase: Data, salt: Data, rounds: UInt32, outputByteCount: Int) throws -> Data { try base.bcryptPBKDF(passphrase: passphrase, salt: salt, rounds: rounds, outputByteCount: outputByteCount) }
    func decryptAESCTR(_ ciphertext: Data, key: Data, iv: Data) throws -> Data { try base.decryptAESCTR(ciphertext, key: key, iv: iv) }
    func pbkdf2(passphrase: Data, salt: Data, iterations: UInt32, prf: PKCS8PBKDF2PRF, outputByteCount: Int) throws -> Data {
        calls.derived()
        if behavior == .denied { throw FTError.storage }
        if behavior == .shortKDF { return Data(repeating: 0, count: outputByteCount - 1) }
        let result = try PKCS8SourcePrimitives.pbkdf2(passphrase: passphrase, salt: salt,
            iterations: iterations, prf: prf, outputByteCount: outputByteCount)
        if behavior == .cancelAfterKDF { withUnsafeCurrentTask { $0?.cancel() } }
        return result
    }
    func decryptAESCBC(_ ciphertext: Data, key: Data, iv: Data) throws -> Data {
        calls.decrypted()
        let result = try base.decryptAESCBC(ciphertext, key: key, iv: iv)
        if behavior == .cancelAfterAES { withUnsafeCurrentTask { $0?.cancel() } }
        return result
    }
}

/// Test-only DER editing for negative fixtures; positive containers always come
/// directly from OpenSSL. This parser only traverses the trusted fixture tree.
private struct PKCS8TestDER {
    var tag: UInt8
    var bytes: Data = Data()
    var children: [Self] = []
    var payload: Data { tag == 0x30 ? children.reduce(Data()) { $0 + $1.encoded() } : bytes }
    static func sequence(_ children: [Self]) -> Self { .init(tag: 0x30, children: children) }
    static func integer(_ value: UInt64) -> Self {
        var value = value, bytes = Data()
        repeat { bytes.insert(UInt8(truncatingIfNeeded: value), at: 0); value >>= 8 } while value > 0
        if bytes.first! & 0x80 != 0 { bytes.insert(0, at: 0) }
        return .init(tag: 2, bytes: bytes)
    }
    func node(_ path: [Int]) -> Self { path.isEmpty ? self : children[path[0]].node(Array(path.dropFirst())) }
    mutating func replace(_ path: [Int], with replacement: Self) {
        if path.isEmpty { self = replacement }
        else { children[path[0]].replace(Array(path.dropFirst()), with: replacement) }
    }
    func encoded() -> Data {
        let body = payload
        var length = body.count, encodedLength = Data()
        repeat { encodedLength.insert(UInt8(truncatingIfNeeded: length), at: 0); length >>= 8 } while length > 0
        if body.count >= 128 { encodedLength.insert(UInt8(0x80 | encodedLength.count), at: 0) }
        return Data([tag]) + encodedLength + body
    }
    func pem() -> Data { Self.pem(encoded()) }
    static func pem(_ der: Data) -> Data {
        Data(("-----BEGIN ENCRYPTED PRIVATE KEY-----\n" + der.base64EncodedString() + "\n-----END ENCRYPTED PRIVATE KEY-----\n").utf8)
    }
    static func parse(pem: String) throws -> Self {
        let lines = pem.split(whereSeparator: \.isNewline)
        guard let der = Data(base64Encoded: lines.dropFirst().dropLast().joined()) else { throw FTError.malformed("test.fixture") }
        var cursor = ByteCursor(der)
        return try read(&cursor)
    }
    private static func read(_ cursor: inout ByteCursor) throws -> Self {
        let tag = UInt8(try cursor.uint(1)), first = try cursor.uint(1)
        let length: UInt64
        if first < 128 { length = first }
        else { length = try cursor.uint(Int(first & 0x7f)) }
        var body = ByteCursor(try cursor.take(Int(length)))
        if tag != 0x30 { return .init(tag: tag, bytes: body.data) }
        var children: [Self] = []
        while body.remaining > 0 { children.append(try read(&body)) }
        return .sequence(children)
    }
}
